      promptGapBounce: "\u4E0A\u306E\u56DE\u7B54\u8349\u6848\u306F\u3001\u672A\u8AAD\u306E\u30AE\u30E3\u30C3\u30D7\uFF08\u7279\u5B9A\u3057\u305F\u306E\u306B\u5B9F\u969B\u306B\u306F\u8AAD\u3093\u3067\u3044\u306A\u3044\u8868\u30FB\u7BC0\u30FB\u30BD\u30FC\u30B9\u3001\u307E\u305F\u306F\u5217\u6319\u3057\u3066\u3044\u306A\u3044\u884C\uFF09\u3092\u81EA\u3089\u8A8D\u3081\u3066\u3044\u307E\u3059\u3002\u8349\u6848\u306F\u5374\u4E0B\u3055\u308C\u307E\u3057\u305F\u3002\u540C\u3058\u8A3C\u62E0\u3067\u66F8\u304D\u76F4\u3055\u306A\u3044\u3067\u304F\u3060\u3055\u3044\uFF1A\u8349\u6848\u304C\u6319\u3052\u305F\u9818\u57DF\u3092\u4ECA\u3059\u3050 read \u3067\u8AAD\u307F\uFF08\u30D5\u30A1\u30A4\u30EB\u30D1\u30B9 + offset/limit\uFF1B\u8868\u306F\u5168\u30BB\u30B0\u30E1\u30F3\u30C8\u3092\u8AAD\u307F\u3001\u5168\u884C\u306E\u5024\u3092\u5217\u6319\uFF09\u3001\u5B8C\u5168\u306A\u5217\u6319\u3092\u542B\u3080\u6700\u7D42\u56DE\u7B54\u3092\u51FA\u3057\u3066\u304F\u3060\u3055\u3044\u3002",
