  /** reload 工具执行器：同命令面板的「Reload app without saving」。
   *  整个应用窗口重载、放弃未保存修改——插件新构建加载的唯一可靠途径。 */
  /** jump 调试工具执行器：走侧栏 openNote 的真实跳行路径，然后回报实际
   *  视图模式 / 光标行 / 滚动位置——引用跳行链路的端到端自动验证。 */
  async runDebugJump(path, line) {
    const sidebarLeaf = this.app.workspace.getLeavesOfType(SEARCH_VIEW_TYPE)[0];
    if (!sidebarLeaf)
      throw new Error("search view not open \u2014 open the Semlink sidebar once first");
    const view = sidebarLeaf.view;
    const resolved = this.app.vault.getAbstractFileByPath(path) instanceof import_obsidian21.TFile;
    await view.openNote(path, "", line);
    await new Promise((r) => window.setTimeout(r, 300));
    const leaf = this.app.workspace.getLeaf(false);
    const v2 = leaf?.view;
    if (!v2)
      return { mode: "none", expectedLine: line, resolved };
    const totalLines = (await this.app.vault.cachedRead(v2.file)).split("\n").length;
    const viewFileCodes = v2.file ? Array.from(v2.file.path.slice(0, 24)).map((c) => c.codePointAt(0).toString(16)).join(",") : null;
    const mode = v2.getMode();
    if (mode === "source") {
      const cur = v2.editor.getCursor();
      const si = v2.editor.getScrollInfo();
      return { mode, resolved, cursorLine: cur.line + 1, expectedLine: line, totalLines, scrollTop: Math.round(si.top), file: v2.file?.path };
    }
    const scroller = v2.contentEl.querySelector(".markdown-preview-view") ?? v2.contentEl;
    return { mode, resolved, scrollTop: Math.round(scroller?.scrollTop ?? -1), scrollHeight: scroller?.scrollHeight ?? -1, expectedLine: line, totalLines, file: v2.file?.path };
  }
